CREATE OR REPLACE FUNCTION public.deliver_push_notification_http_fnc(p_user_id uuid, p_title text, p_body text, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_supabase_url text := 'https://yvwpchffctiagevpqgwy.supabase.co';
    v_service_role_key text;
    v_notification_id uuid;
BEGIN
    -- Phase 6: best-effort extraction for failure-tracking context only -- never affects delivery,
    -- and a bad/missing value here can never abort the function (guarded sub-block).
    BEGIN
        v_notification_id := NULLIF(p_data->>'notification_id', '')::uuid;
    EXCEPTION WHEN OTHERS THEN
        v_notification_id := NULL;
    END;

    SELECT decrypted_secret INTO v_service_role_key
    FROM vault.decrypted_secrets
    WHERE name = 'supabase_service_role_key'
    LIMIT 1;

    IF v_service_role_key IS NULL THEN
        RAISE WARNING 'Push notification delivery skipped: vault secret "supabase_service_role_key" is not configured. Run vault.create_secret(...) once via the Supabase Dashboard SQL Editor.';
        BEGIN
            INSERT INTO public.notification_failures (
                failure_stage, source_function, notification_type, reference_id, user_id,
                notification_id, error_message
            ) VALUES (
                'enqueue', 'deliver_push_notification_http_fnc', p_data->>'type',
                NULLIF(p_data->>'reference_id', '')::uuid, p_user_id, v_notification_id,
                'vault secret "supabase_service_role_key" is not configured'
            );
        EXCEPTION WHEN OTHERS THEN
            -- Failure-tracking must never itself introduce a new failure mode.
            NULL;
        END;
        RETURN;
    END IF;

    PERFORM net.http_post(
        url := v_supabase_url || '/functions/v1/send-push-notification',
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_service_role_key
        ),
        body := jsonb_build_object(
            'user_id', p_user_id,
            'title', p_title,
            'body', p_body,
            'data', p_data
        ),
        timeout_milliseconds := 5000
    );
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Failed to send push notification HTTP call: %', SQLERRM;
    BEGIN
        INSERT INTO public.notification_failures (
            failure_stage, source_function, notification_type, reference_id, user_id,
            notification_id, error_code, error_message
        ) VALUES (
            'push_delivery', 'deliver_push_notification_http_fnc', p_data->>'type',
            NULLIF(p_data->>'reference_id', '')::uuid, p_user_id, v_notification_id,
            SQLSTATE, left(SQLERRM, 2000)
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
END;
$function$

CREATE OR REPLACE FUNCTION public.on_new_chat_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_recipient_user_id uuid := NULL;
    v_customer_user_id uuid := NULL;
    v_rider_user_id uuid := NULL;
    v_order_rider_id uuid := NULL;
    v_sender_name text := 'Someone';
BEGIN
    -- Get sender name if possible
    SELECT COALESCE(full_name, 'Someone') INTO v_sender_name 
    FROM public.users 
    WHERE id = NEW.sender_id;

    IF NEW.order_id IS NOT NULL THEN
        -- Order chat
        SELECT user_id, rider_id INTO v_customer_user_id, v_order_rider_id 
        FROM public.orders 
        WHERE id = NEW.order_id;

        -- Get rider's user_id
        IF NEW.rider_id IS NOT NULL THEN
            SELECT user_id INTO v_rider_user_id FROM public.riders WHERE id = NEW.rider_id;
        ELSIF v_order_rider_id IS NOT NULL THEN
            SELECT user_id INTO v_rider_user_id FROM public.riders WHERE id = v_order_rider_id;
        END IF;

        IF NEW.sender_id = v_customer_user_id THEN
            v_recipient_user_id := v_rider_user_id;
        ELSIF NEW.sender_id = v_rider_user_id THEN
            v_recipient_user_id := v_customer_user_id;
        END IF;
    ELSE
        -- Support chat
        IF NEW.user_id IS NOT NULL AND NEW.sender_id != NEW.user_id THEN
            v_recipient_user_id := NEW.user_id;
        END IF;
    END IF;

    -- Send notification if recipient is determined
    IF v_recipient_user_id IS NOT NULL THEN
        PERFORM public.send_push_notification_fnc(
            v_recipient_user_id,
            v_sender_name,
            NEW.message,
            jsonb_build_object(
                'type', 'chat_message',
                'order_id', NEW.order_id,
                'message_id', NEW.id,
                'sender_type', NEW.sender_type
            )
        );
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_chat_before_intercity_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.order_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Admin/support messages are never blocked, matching the existing RLS policy's own carve-out.
    IF EXISTS (
        SELECT 1 FROM public.users
        WHERE id = auth.uid() AND role IN ('admin', 'support')
    ) THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.intercity_requests ir
        WHERE ir.parcel_id = NEW.order_id
          AND ir.status = 'request_sent'
    ) THEN
        RAISE EXCEPTION 'You can send messages after the request is accepted.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_push_notification_fnc(p_user_id uuid, p_title text, p_body text, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_notification_type text := COALESCE(p_data->>'type', 'general');
    v_reference_id uuid := NULL;
    v_reference_type text := NULL;
BEGIN
    -- Extract reference info if present
    IF p_data ? 'order_id' THEN
        BEGIN
            v_reference_id := (p_data->>'order_id')::uuid;
            v_reference_type := 'order';
        EXCEPTION WHEN OTHERS THEN
            -- Ignore formatting errors
        END;
    ELSIF p_data ? 'payment_id' THEN
        BEGIN
            v_reference_id := (p_data->>'payment_id')::uuid;
            v_reference_type := 'payment';
        EXCEPTION WHEN OTHERS THEN
            -- Ignore formatting errors
        END;
    END IF;

    -- Insert into notifications log table (which triggers async HTTP delivery)
    INSERT INTO public.notifications (
        user_id,
        title,
        body,
        notification_type,
        reference_id,
        reference_type,
        payload
    ) VALUES (
        p_user_id,
        p_title,
        p_body,
        v_notification_type,
        v_reference_id,
        v_reference_type,
        p_data
    );
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'send_push_notification_fnc: failed to insert notification for user %: %', p_user_id, SQLERRM;
    BEGIN
        INSERT INTO public.notification_failures (
            failure_stage, source_function, notification_type, reference_id, user_id,
            error_code, error_message
        ) VALUES (
            'insert', 'send_push_notification_fnc', v_notification_type, v_reference_id, p_user_id,
            SQLSTATE, left(SQLERRM, 2000)
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
END;
$function$
